import{_ as e,c as t,o as i,ae as r}from"./chunks/framework.CHDT0Kbg.js";const _=JSON.parse('{"title":"Persim とは","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/introduction.md","filePath":"ja/guide/introduction.md","lastUpdated":1795170900000}'),l={name:"ja/guide/introduction.md"};function o(n,a,s,d,c,u){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="persim-とは" tabindex="-1">Persim とは <a class="header-anchor" href="#persim-とは" aria-label="Permalink to &quot;Persim とは&quot;">​</a></h1><p>開いた瞬間から使える Mac ブラウザー。タブ、検索、ブックマーク、ダウンロードが揃っています。</p><h2 id="まずできること" tabindex="-1">まずできること <a class="header-anchor" href="#まずできること" aria-label="Permalink to &quot;まずできること&quot;">​</a></h2><ul><li><strong>検索と閲覧</strong>：アドレスバーに URL も質問も入力できます。よく行くサイトが先に候補として出ます。</li><li><strong>タブとウィンドウ</strong>：作成、ドラッグ、グループ化、ミュート、ホバーでプレビュー。⌘⇧A でタブを検索できます。</li><li><strong>あとで見つける</strong>：ブックマーク、履歴、ダウンロード、そして「前回のセッションを復元」。</li></ul><h2 id="少し静かに" tabindex="-1">少し静かに <a class="header-anchor" href="#少し静かに" aria-label="Permalink to &quot;少し静かに&quot;">​</a></h2><ul><li>広告ブロックは購読ルール、独自ルール、許可リストに対応。</li><li>ページの強制ダーク表示、タブのミュート、ポップアップ制限は設定で切り替えます。</li><li>プライベートウィンドウ（⌘⇧N）では履歴を残しません。</li></ul><h2 id="動画と長文" tabindex="-1">動画と長文 <a class="header-anchor" href="#動画と長文" aria-label="Permalink to &quot;動画と長文&quot;">​</a></h2><ul><li>メディアパネルにページ内の動画が並び、保存するとひとつの MP4 になります。</li><li>リーディングモード（⌘⇧R）は本文だけを残します。表示範囲や全ページを PDF で保存できます。</li></ul><h2 id="自分らしく" tabindex="-1">自分らしく <a class="header-anchor" href="#自分らしく" aria-label="Permalink to &quot;自分らしく&quot;">​</a></h2><p>ライト / ダーク / システムに従う、6 色のアクセント、ブックマークバーの 3 モード、25 言語の UI。外観はすぐ反映され、言語はウィンドウを開き直すと反映されます。</p>',10)])])}const m=e(l,[["render",o]]);export{_ as __pageData,m as default};
